using System;
using Febucci.UI;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class EventButton : ZoomableInstance
{
	[Header("Components")]
	[SerializeField]
	private TextMeshProUGUI loreText;

	[SerializeField]
	private FMODEventReferenceReference genericClickFMODEventReferenceReference;

	[SerializeField]
	[HideIf("shrine")]
	private TextAnimatorPlayer loreTextAnimatorPlayer;

	[SerializeField]
	[HideIf("shrine")]
	private TextMeshProUGUI resultText;

	[SerializeField]
	[HideIf("shrine")]
	private TextAnimatorPlayer resultTextAnimatorPlayer;

	[SerializeField]
	private Button button;

	[SerializeField]
	[HideIf("shrine")]
	private FadeCanvasGroup fadeCanvasGroup;

	[SerializeField]
	[HideIf("shrine")]
	private CanvasGroup canvasGroup;

	[SerializeField]
	[HideIf("shrine")]
	private OmenInstance omenInstance;

	[SerializeField]
	[HideIf("shrine")]
	private OmensListsList omensListsList;

	[SerializeField]
	[HideIf("shrine")]
	private DiceFaceInstance2D diceFaceInstance2D;

	[SerializeField]
	[HideIf("shrine")]
	private EffectInstance effectInstance;

	[Header("Text Width")]
	[SerializeField]
	private float defaultTextWidth = 725f;

	[SerializeField]
	private float reducedTextWidth = 510f;

	[Header("Shrine")]
	[SerializeField]
	private bool shrine;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnEventButtonClickEvent;

	private EventButtonData eventButtonData;

	private EventsPanel eventsPanel;

	private int buttonIndex;

	private float textsUpdateFadeOutDuration;

	public EventButtonData EventButtonData => eventButtonData;

	public EventsPanel EventsPanel => eventsPanel;

	public int ButtonIndex => buttonIndex;

	public void Initialize(EventButtonData eventButtonData, EventsPanel eventsPanel, int buttonIndex, float delayToShowText, bool firstInitialize, float textsUpdateFadeOutDuration)
	{
		this.eventButtonData = eventButtonData;
		this.eventsPanel = eventsPanel;
		this.buttonIndex = buttonIndex;
		this.textsUpdateFadeOutDuration = textsUpdateFadeOutDuration;
		bool flag = false;
		if (eventButtonData.eventAction is OmenDataEventAction)
		{
			omenInstance.gameObject.SetActive(value: true);
			OmenDataEventAction omenDataEventAction = eventButtonData.eventAction as OmenDataEventAction;
			omenInstance.Initialize(omenDataEventAction.OmenData);
			omensListsList.BlessingDiscovered(omenDataEventAction.OmenData);
			flag = true;
		}
		else
		{
			omenInstance.gameObject.SetActive(value: false);
		}
		if (eventButtonData.eventAction is ForgeDiceRewardEventAction)
		{
			diceFaceInstance2D.gameObject.SetActive(value: true);
			ForgeDiceRewardEventAction forgeDiceRewardEventAction = eventButtonData.eventAction as ForgeDiceRewardEventAction;
			diceFaceInstance2D.Initialize(null, forgeDiceRewardEventAction.ForgeDiceReward.DiceFace);
			flag = true;
		}
		else if (eventButtonData.eventAction is DiePrototypeCreationEventAction)
		{
			diceFaceInstance2D.gameObject.SetActive(value: true);
			DiePrototypeCreationEventAction diePrototypeCreationEventAction = eventButtonData.eventAction as DiePrototypeCreationEventAction;
			diceFaceInstance2D.Initialize(null, diePrototypeCreationEventAction.Die.GetDiceFaces().First());
			flag = true;
		}
		else if (eventButtonData.eventAction is ChangeStarterWithANewDieEventAction)
		{
			diceFaceInstance2D.gameObject.SetActive(value: true);
			ChangeStarterWithANewDieEventAction changeStarterWithANewDieEventAction = eventButtonData.eventAction as ChangeStarterWithANewDieEventAction;
			diceFaceInstance2D.Initialize(null, changeStarterWithANewDieEventAction.Dice.GetDiceFaces().First());
			flag = true;
		}
		else
		{
			diceFaceInstance2D.gameObject.SetActive(value: false);
		}
		if (eventButtonData.eventAction is StartingEffectToSentinelEventAction)
		{
			effectInstance.gameObject.SetActive(value: true);
			StartingEffectToSentinelEventAction obj = eventButtonData.eventAction as StartingEffectToSentinelEventAction;
			StartingEffect startingEffect = obj.CompanionStartingEffectReward.StartingEffect;
			effectInstance.Initialize(startingEffect.Effect, startingEffect.EffectAmount, null, null, effectFeedback: false, callEffectsCallbacks: false, gainingEffectVFXAndSFX: false);
			obj.InitializeEffectInstance(effectInstance);
			flag = true;
		}
		else
		{
			effectInstance.gameObject.SetActive(value: false);
		}
		if (flag)
		{
			resultText.rectTransform.SetSizeDeltaX(reducedTextWidth);
			loreText.rectTransform.SetSizeDeltaX(reducedTextWidth);
		}
		else
		{
			resultText.rectTransform.SetSizeDeltaX(defaultTextWidth);
			loreText.rectTransform.SetSizeDeltaX(defaultTextWidth);
		}
		enableActionDescriptionPanel = eventButtonData.eventAction.EventActionWithTooltip;
		if (firstInitialize)
		{
			eventButtonData.eventAction.FirstInitialize(this);
			canvasGroup.alpha = 1f;
			canvasGroup.interactable = true;
			canvasGroup.blocksRaycasts = true;
		}
		else
		{
			fadeCanvasGroup.Fade(toggle: true);
		}
		eventButtonData.eventAction.Initialize(this);
		UpdateIsEventButtonEnabled();
		button.onClick.RemoveAllListeners();
		button.onClick.AddListener(delegate
		{
			genericClickFMODEventReferenceReference.PlaySFX();
			if (eventButtonData.IgnoreFirstButtonClickLogicAndUpdateEventDescriptionAndButtons && firstInitialize)
			{
				EventButtonPressedUpdateEventDescriptionAnButtons();
			}
			else
			{
				eventButtonData.eventAction.ExecuteAction(this);
				if (eventButtonData.eventAction.EventButtonPressedUpdateEventDescriptionAndButtons)
				{
					EventButtonPressedUpdateEventDescriptionAnButtons();
				}
				else if (!eventButtonData.eventAction.DontCallOnEventButtonPressed)
				{
					EventButtonPressedFadeOutEventsPanel(eventButtonData.eventAction.DontStoreEventsPanel, eventButtonData.eventAction.StoreEventsPanelDelay, eventButtonData.eventAction.IgnoreDisableRewardsAnimation);
				}
			}
			OnEventButtonClickEvent.Raise();
			if (eventButtonData.eventAction != null)
			{
				eventsPanel.onEventButtonPressed?.Invoke(eventButtonData.eventAction);
			}
		});
		UpdateEventButtonText();
		if (delayToShowText == 0f)
		{
			StartShowingButtonTexts();
		}
		else if (delayToShowText > 0f)
		{
			InvokeAlternatives.Invoke(this, delayToShowText, delegate
			{
				StartShowingButtonTexts();
			});
		}
		void EventButtonPressedUpdateEventDescriptionAnButtons()
		{
			eventsPanel.EventButtonPressedUpdateEventDescriptionAndButtons(buttonIndex, eventButtonData.eventAction.InstantlyUpdate, eventButtonData.eventAction.EnableCustomEventButtonOnUpdate ? eventButtonData.eventAction.CustomEventButtonOnUpdate : null);
		}
	}

	public void StartShowingButtonTexts()
	{
		loreTextAnimatorPlayer.StartShowingText(resetVisibleCharacters: true);
		resultTextAnimatorPlayer.StartShowingText(resetVisibleCharacters: true);
	}

	public void Initialize(Reward reward)
	{
		loreText.SetText(reward.RewardName);
		button.onClick.RemoveAllListeners();
		button.onClick.AddListener(delegate
		{
			reward.GetReward();
			eventsPanel.EventButtonPressedFadeOutEventsPanel();
		});
	}

	public override void InitializeActionDescriptionPanel()
	{
		if (eventButtonData.eventAction.EventActionWithTooltip)
		{
			eventButtonData.eventAction.InitializeActionDescriptionPanel(actionDescriptionPanel);
		}
	}

	public void UpdateEventButtonText()
	{
		loreText.SetText(eventButtonData.GetEventButtonLoreText());
		string eventButtonResultText = eventButtonData.GetEventButtonResultText();
		if (eventButtonResultText == "")
		{
			resultText.transform.parent.gameObject.SetActive(value: false);
			return;
		}
		resultText.transform.parent.gameObject.SetActive(value: true);
		resultText.SetText(eventButtonResultText);
	}

	public void UpdateIsEventButtonEnabled()
	{
		ToggleButton(eventButtonData.IsEventButtonEnabled());
	}

	public void EventButtonPressedFadeOutEventsPanel(bool dontStoreAfterFadeOut, float storeEventsPanelDelay, bool ignoreDisableRewardsAnimation)
	{
		eventsPanel.EventButtonPressedFadeOutEventsPanel(dontStoreAfterFadeOut, storeEventsPanelDelay, ignoreDisableRewardsAnimation);
	}

	public void ToggleBackgroundPurpleForTransitionIgnoreParentGroups(bool value)
	{
		eventsPanel.ToggleBackgroundPurpleForTransitionIgnoreParentGroups(value);
	}

	public void ToggleButton(bool value)
	{
		button.interactable = value;
	}

	public void FadeCanvasGroupFadeOut(Action afterFadeAction = null)
	{
		fadeCanvasGroup.Fade(toggle: false, afterFadeAction, textsUpdateFadeOutDuration);
	}

	public void FadeCanvasGroupFadeIn()
	{
		fadeCanvasGroup.Fade(toggle: true);
	}

	public void SetTextsToEmptyAndAlphaCanvasGroupToZero()
	{
		canvasGroup.alpha = 0f;
		loreText.SetText("");
		resultText.SetText("");
	}

	public void InitializeShrine(EventButtonData eventButtonData, ShrineProp shrineProp)
	{
		this.eventButtonData = eventButtonData;
		eventButtonData.eventAction.Initialize(this);
		UpdateIsEventButtonEnabled();
		button.onClick.RemoveAllListeners();
		button.onClick.AddListener(delegate
		{
			genericClickFMODEventReferenceReference.PlaySFX();
			eventButtonData.eventAction.ExecuteAction(this);
			shrineProp.EventButtonPressed();
		});
		loreText.SetText(eventButtonData.GetEventButtonLoreText());
	}
}
